begin;
do $$
declare
 a uuid:=gen_random_uuid(); u uuid:=gen_random_uuid(); other_user uuid:=gen_random_uuid();
 sa uuid:=gen_random_uuid(); su uuid:=gen_random_uuid(); so uuid:=gen_random_uuid();
 atoken text; utoken text; o jsonb; i uuid; card uuid; key_id uuid;
begin
 insert into auth.users(id,email) values(a,'vault-admin-fixture@example.invalid'),(u,'vault-sales-fixture@example.invalid'),(other_user,'vault-other-fixture@example.invalid');
 insert into auth.sessions(id,user_id,created_at,updated_at) values(sa,a,now(),now()),(su,u,now(),now()),(so,other_user,now(),now());
 insert into public.a1_staff(user_id,is_admin) values(a,true),(u,false),(other_user,false);
 insert into public.a1_activity_sessions(user_id,auth_session_id,display_name,idle_exempt) values(a,sa,'Vault Admin',true),(u,su,'Vault Sales',false),(other_user,so,'Other',false);
 begin perform public.a1_vault_service(u,su,'unlock');raise exception 'Unpermitted user unlocked vault';exception when insufficient_privilege then null;end;
 o:=public.a1_vault_service(a,sa,'unlock');atoken:=o->>'unlock_token';
 if (o->>'expires_at')::timestamptz<>now()+interval '30 minutes' or not exists(select 1 from a1_vault_private.a1_vault_unlocks where user_id=a and expires_at=now()+interval '30 minutes') then raise exception 'Admin unlock must last 30 minutes';end if;
 o:=public.a1_vault_service(a,sa,'save',jsonb_build_object('unlock_token',atoken,'kind','login','label','Synthetic login','details',jsonb_build_object('url','https://tickets.example.invalid/','username','fixture','password','SYNTHETIC-NOT-A-REAL-PASSWORD')));
 i:=(o->>'id')::uuid;
 card:=(public.a1_vault_service(a,sa,'save',jsonb_build_object('unlock_token',atoken,'kind','card','label','Synthetic card','details',jsonb_build_object('number','4111111111111111','cardholder','Test Company','expiry','12/30','cvv','DO-NOT-STORE')))->>'id')::uuid;
 perform public.a1_vault_service(a,sa,'permissions',jsonb_build_object('unlock_token',atoken,'user_id',u,'passwords',true,'cards',false,'can_edit',false));
 o:=public.a1_vault_service(u,su,'unlock',jsonb_build_object('admin',true,'timeout_minutes',30));utoken:=o->>'unlock_token';
 if (o->>'expires_at')::timestamptz<>now()+interval '5 minutes' or not exists(select 1 from a1_vault_private.a1_vault_unlocks where user_id=u and expires_at=now()+interval '5 minutes') then raise exception 'Sales unlock must remain five minutes regardless of client claims';end if;
 if jsonb_array_length(public.a1_vault_service(u,su,'list',jsonb_build_object('unlock_token',utoken)))<>0 then raise exception 'Unassigned entries leaked';end if;
 begin perform public.a1_vault_service(u,su,'reveal',jsonb_build_object('unlock_token',utoken,'id',i));raise exception 'Unassigned password leaked';exception when insufficient_privilege then null;end;
 perform public.a1_vault_service(a,sa,'grants',jsonb_build_object('unlock_token',atoken,'id',i,'users',jsonb_build_array(u)));
 utoken:=public.a1_vault_service(u,su,'unlock')->>'unlock_token';
 o:=public.a1_vault_service(u,su,'list',jsonb_build_object('unlock_token',utoken));
 if jsonb_array_length(o)<>1 or o::text like '%SYNTHETIC-NOT-A-REAL-PASSWORD%' then raise exception 'Wrong metadata exposure';end if;
 if public.a1_vault_service(u,su,'reveal',jsonb_build_object('unlock_token',utoken,'id',i))->'details'->>'password'<>'SYNTHETIC-NOT-A-REAL-PASSWORD' then raise exception 'Assigned password unavailable';end if;
 begin perform public.a1_vault_service(u,su,'accounts',jsonb_build_object('unlock_token',utoken));raise exception 'Sales can manage accounts';exception when insufficient_privilege then null;end;
 begin perform public.a1_vault_service(u,su,'permissions',jsonb_build_object('unlock_token',utoken,'user_id',u,'cards',true));raise exception 'Sales can grant permissions';exception when insufficient_privilege then null;end;
 begin perform public.a1_vault_service(u,su,'grants',jsonb_build_object('unlock_token',utoken,'id',i,'users',jsonb_build_array(other_user)));raise exception 'Sales can share';exception when insufficient_privilege then null;end;
 begin perform public.a1_vault_service(u,su,'delete',jsonb_build_object('unlock_token',utoken,'id',i,'version',1));raise exception 'Read-only user can delete';exception when insufficient_privilege then null;end;
 begin perform public.a1_vault_service(u,su,'reveal',jsonb_build_object('unlock_token',utoken,'id',card));raise exception 'Card access leaked';exception when insufficient_privilege then null;end;
 begin perform public.a1_vault_service(other_user,so,'list',jsonb_build_object('unlock_token',utoken));raise exception 'Token shared between users';exception when insufficient_privilege then null;end;
 perform public.a1_vault_service(a,sa,'permissions',jsonb_build_object('unlock_token',atoken,'user_id',u,'passwords',true,'cards',false,'can_edit',true));
 utoken:=public.a1_vault_service(u,su,'unlock')->>'unlock_token';
 perform public.a1_vault_service(u,su,'save',jsonb_build_object('unlock_token',utoken,'id',i,'kind','login','version',1,'label','Edited fixture','details',jsonb_build_object('url','https://tickets.example.invalid/','password','UPDATED-SYNTHETIC')));
 begin perform public.a1_vault_service(u,su,'save',jsonb_build_object('unlock_token',utoken,'id',i,'kind','login','version',1,'label','Overwrite'));raise exception 'Stale version overwritten';exception when raise_exception then if sqlerrm<>'This entry changed. Refresh before saving' then raise;end if;end;
 update a1_vault_private.a1_vault_unlocks set expires_at=now()-interval '1 second' where user_id=u;
 begin perform public.a1_vault_service(u,su,'reveal',jsonb_build_object('unlock_token',utoken,'id',i));raise exception 'Expired unlock accepted';exception when insufficient_privilege then null;end;
 utoken:=public.a1_vault_service(u,su,'unlock')->>'unlock_token';
 perform public.a1_vault_service(a,sa,'grants',jsonb_build_object('unlock_token',atoken,'id',i,'users','[]'::jsonb));
 utoken:=public.a1_vault_service(u,su,'unlock')->>'unlock_token';
 begin perform public.a1_vault_service(u,su,'reveal',jsonb_build_object('unlock_token',utoken,'id',i));raise exception 'Revoked item remains accessible';exception when insufficient_privilege then null;end;
 perform public.a1_vault_service(a,sa,'permissions',jsonb_build_object('unlock_token',atoken,'user_id',u,'passwords',false));
 begin perform public.a1_vault_service(u,su,'list',jsonb_build_object('unlock_token',utoken));raise exception 'Revoked category remains accessible';exception when insufficient_privilege then null;end;
 for n in 1..5 loop o:=public.a1_vault_service(a,sa,'unlock_attempt');end loop;
 if (public.a1_vault_service(a,sa,'unlock_attempt')->>'allowed')::boolean then raise exception 'Unlock rate limit failed';end if;
 if exists(select 1 from a1_vault_private.a1_vault_events where actor_id=a and row_to_json(a1_vault_events)::text like '%SYNTHETIC-NOT-A-REAL-PASSWORD%') then raise exception 'Secret in audit history';end if;
 if public.a1_vault_service(a,sa,'reveal',jsonb_build_object('unlock_token',atoken,'id',card))->'details' ? 'cvv' then raise exception 'Unexpected CVV stored';end if;
 update public.a1_activity_sessions set ended_at=now() where user_id=a;
 begin perform public.a1_vault_service(a,sa,'list',jsonb_build_object('unlock_token',atoken));raise exception 'Ended dashboard session accepted';exception when insufficient_privilege then null;end;
 delete from auth.sessions where id=su;
 begin perform public.a1_vault_service(u,su,'status');raise exception 'Revoked Auth session accepted';exception when insufficient_privilege then null;end;
 if has_function_privilege('authenticated','public.a1_vault_service(uuid,uuid,text,jsonb)','EXECUTE') or has_function_privilege('anon','public.a1_vault_service(uuid,uuid,text,jsonb)','EXECUTE') then raise exception 'Client can bypass Edge verification';end if;
 if has_table_privilege('authenticated','a1_vault_private.a1_vault_items','SELECT') or has_table_privilege('anon','a1_vault_private.a1_vault_items','SELECT') then raise exception 'Client can read vault tables';end if;
 if exists(select 1 from public.a1_staff where user_id=u and is_admin) then raise exception 'Sales user promoted';end if;
end $$;
rollback;
select 'PASS: assignment, category permissions, admin isolation, editing, concurrency, revocation, session expiry, rate limiting and secret-free audit' as result;
